options.customCss:
:root {
	/* =========================
	   Typography
	========================= */
	--font-family: 'Inter', 'Open Sans', sans-serif;
	--font-weight-normal: 400;
	--font-weight-bold: 600;

	--font-size-body: 13px;
	--font-size-label: 13px;
	--font-size-test-notice: 12px;
	--font-size-input: 14px;
	--font-size-header: 28px;
	--font-size-paragraph: 14px;
	--font-size-link: 13px;
	--font-size-error: 12px;
	--font-size-html-h1: 30px;
	--font-size-html-h2: 22px;
	--font-size-html-h3: 18px;
	--font-size-html-h4: 16px;
	--font-size-html-h5: 13px;
	--font-size-html-h6: 11px;
	--font-size-subheader: 14px;


	/* =========================
	   Blue Glassmorphism Colors
	========================= */

	/* Background */
	--color-background: #071426;

	/* Glass Card */
	--color-card-bg: rgba(255, 255, 255, 0.09);
	--color-card-border: rgba(255, 255, 255, 0.16);
	--color-card-shadow: rgba(0, 0, 0, 0.30);

	/* Text */
	--color-header: #ffffff;
	--color-label: rgba(255, 255, 255, 0.85);
	--color-html-text: rgba(255, 255, 255, 0.78);
	--color-header-subtext: rgba(255, 255, 255, 0.60);

	/* Inputs */
	--color-input-border: rgba(255, 255, 255, 0.15);
	--color-input-text: #ffffff;
	--color-focus-border: #3b82f6;

	/* Primary Blue */
	--color-submit-btn-bg: linear-gradient(
		135deg,
		#2563eb 0%,
		#3b82f6 50%,
		#60a5fa 100%
	);

	--color-submit-btn-text: #ffffff;

	/* Links */
	--color-link: #93c5fd;
	--color-html-link: #60a5fa;

	/* Errors */
	--color-error: #fb7185;
	--color-required: #60a5fa;

	/* Clear button */
	--color-clear-button-bg: rgba(255, 255, 255, 0.12);


	/* =========================
	   Border Radius
	========================= */
	--border-radius-card: 24px;
	--border-radius-input: 12px;
	--border-radius-clear-btn: 50%;
	--card-border-radius: 24px;


	/* =========================
	   Spacing
	========================= */
	--padding-container-top: 40px;
	--padding-card: 36px;

	--padding-test-notice-vertical: 12px;
	--padding-test-notice-horizontal: 20px;

	--margin-bottom-card: 20px;

	--padding-form-input: 14px;

	--card-padding: 36px;
	--card-margin-bottom: 20px;


	/* =========================
	   Dimensions
	========================= */
	--container-width: 440px;
	--submit-btn-height: 52px;
	--checkbox-size: 18px;


	/* =========================
	   Glassmorphism Effects
	========================= */

	--box-shadow-card:
		0 25px 60px rgba(0, 0, 0, 0.35),
		0 8px 30px rgba(37, 99, 235, 0.12);

	--opacity-placeholder: 0.45;

	/* Glass blur */
	--glass-blur: 20px;

	/* Blue glow */
	--blue-glow: rgba(59, 130, 246, 0.35);
}

/* =========================
   MODERN BLUE GLASS LOGIN
========================= */

body {
	background:
		radial-gradient(
			circle at 15% 20%,
			rgba(37, 99, 235, 0.25),
			transparent 35%
		),
		radial-gradient(
			circle at 85% 80%,
			rgba(59, 130, 246, 0.20),
			transparent 35%
		),
		linear-gradient(
			135deg,
			#020617 0%,
			#071426 45%,
			#0b1d36 100%
		);

	min-height: 100vh;
	color: #fff;
}


/* Glass Card */

.card,
form {
	background: rgba(255, 255, 255, 0.08) !important;

	backdrop-filter: blur(20px);
	-webkit-backdrop-filter: blur(20px);

	border: 1px solid rgba(255, 255, 255, 0.14) !important;

	border-radius: 24px !important;

	box-shadow:
		0 25px 60px rgba(0, 0, 0, 0.35),
		0 0 40px rgba(37, 99, 235, 0.08);

}


/* Headings */

h1,
h2,
h3,
.header {
	color: #ffffff !important;
	font-weight: 600;
	letter-spacing: -0.5px;
}


/* Labels */

label {
	color: rgba(255, 255, 255, 0.82) !important;
	font-weight: 500;
}


/* Inputs */

input,
textarea,
select {
	background: rgba(255, 255, 255, 0.07) !important;

	border: 1px solid rgba(255, 255, 255, 0.14) !important;

	border-radius: 12px !important;

	color: #ffffff !important;

	transition:
		border-color 0.25s ease,
		box-shadow 0.25s ease,
		background 0.25s ease,
		transform 0.2s ease;
}


/* Input focus */

input:focus,
textarea:focus,
select:focus {
	background: rgba(255, 255, 255, 0.10) !important;

	border-color: #3b82f6 !important;

	box-shadow:
		0 0 0 3px rgba(59, 130, 246, 0.15),
		0 0 20px rgba(59, 130, 246, 0.12);

	outline: none !important;
}


/* Placeholder */

input::placeholder,
textarea::placeholder {
	color: rgba(255, 255, 255, 0.40) !important;
}


/* Submit Button */

button[type="submit"],
input[type="submit"] {
	height: 52px !important;

	background:
		linear-gradient(
			135deg,
			#2563eb,
			#3b82f6,
			#60a5fa
		) !important;

	color: #ffffff !important;

	border: none !important;

	border-radius: 12px !important;

	font-weight: 600;

	font-size: 14px;

	cursor: pointer;

	box-shadow:
		0 10px 25px rgba(37, 99, 235, 0.30);

	transition:
		transform 0.2s ease,
		box-shadow 0.2s ease,
		filter 0.2s ease;
}


/* Button Hover */

button[type="submit"]:hover,
input[type="submit"]:hover {
	transform: translateY(-2px);

	box-shadow:
		0 14px 30px rgba(37, 99, 235, 0.40);

	filter: brightness(1.08);
}


/* Button Click */

button[type="submit"]:active,
input[type="submit"]:active {
	transform: translateY(0);
}


/* Links */

a {
	color: #60a5fa !important;

	text-decoration: none;

	transition:
		color 0.2s ease,
		text-shadow 0.2s ease;
}

a:hover {
	color: #93c5fd !important;

	text-shadow:
		0 0 12px rgba(96, 165, 250, 0.5);
}


/* Error */

.error,
.form-error {
	color: #fb7185 !important;
}


/* Checkbox */

input[type="checkbox"] {
	accent-color: #3b82f6;
}


/* Test Notice */

.test-notice {
	background: rgba(59, 130, 246, 0.08) !important;

	border: 1px solid rgba(96, 165, 250, 0.18) !important;

	color: #93c5fd !important;

	border-radius: 12px;
}


/* Smooth everything */

* {
	box-sizing: border-box;
}

body::before,
body::after {
	content: "";
	position: fixed;

	width: 320px;
	height: 320px;

	border-radius: 50%;

	background: rgba(37, 99, 235, 0.18);

	filter: blur(90px);

	pointer-events: none;

	z-index: 0;
}

body::before {
	top: -100px;
	left: -100px;
}

body::after {
	right: -100px;
	bottom: -100px;

	background: rgba(59, 130, 246, 0.14);
}
